DROP TABLE IF EXISTS `patient_enrolment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patient_enrolment` (
  `enrolment_row_id` int(11) NOT NULL AUTO_INCREMENT,
  `enrolment_uid` varchar(20) NOT NULL,
  `surname` varchar(25) NOT NULL,
  `firstname` varchar(25) NOT NULL,
  `othername` varchar(25) DEFAULT NULL,
  `gender_id` int(11) NOT NULL,
  `marital_status_id` int(11) NOT NULL,
  `date_of_birth` date NOT NULL,
  `phone_number` varchar(13) NOT NULL,
  `email` varchar(50) DEFAULT NULL,
  `blood_group_id` int(11) DEFAULT NULL,
  `genotype_id` int(11) DEFAULT NULL,
  `nationality_id` int(11) NOT NULL,
  `community_id` int(11) NOT NULL,
  `indigene_status_id` int(11) NOT NULL,
  `date_of_enrolment` date NOT NULL,
  `enrollment_by` int(11) NOT NULL,
  `picture_id` int(11) NOT NULL,
  `fingerprint_id` int(11) DEFAULT NULL,
  `deleted_yn` char(1) DEFAULT 'N',
  `last_updated_by` int(11) DEFAULT NULL,
  `last_updated_date` datetime DEFAULT NULL,
  `contact_address` varchar(150) DEFAULT NULL,
  `client_pref_hf_id` int(11) DEFAULT NULL,
  `notif_sent` varchar(10) DEFAULT NULL,
  `state_of_origin` varchar(50) DEFAULT NULL,
  `corp_organization_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`enrolment_row_id`,`enrolment_uid`,`enrollment_by`),
  UNIQUE KEY `surname` (`surname`,`firstname`,`gender_id`,`date_of_birth`),
  KEY `patient_enrol_gender_gender_id_fk_idx` (`gender_id`),
  KEY `patient_enrol_marital_status_mar_id_fk_idx` (`marital_status_id`),
  KEY `patient_enrol_genotype_type_id_fk_idx` (`genotype_id`),
  KEY `patient_enrol_ind_stat_ind_stat_id_fk_idx` (`indigene_status_id`),
  KEY `patient_enrol_users_userid_fk_idx` (`enrollment_by`),
  KEY `patient_enrol_nationality_id_fk_idx` (`nationality_id`),
  KEY `patient_enrol_bloodgroup_id_fk_idx` (`blood_group_id`),
  KEY `patient_enrolment_communities_id_fk` (`community_id`),
  CONSTRAINT `patient_enrol_gender_gender_id_fk` FOREIGN KEY (`gender_id`) REFERENCES `gender` (`gender_id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `patient_enrol_ind_stat_ind_stat_id_fk` FOREIGN KEY (`indigene_status_id`) REFERENCES `indigene_status` (`indigene_status_id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `patient_enrol_marital_status_mar_id_fk` FOREIGN KEY (`marital_status_id`) REFERENCES `marital_status` (`marital_status_id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `patient_enrol_nationality_id_fk` FOREIGN KEY (`nationality_id`) REFERENCES `nationality` (`nationality_id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `patient_enrol_users_userid_fk` FOREIGN KEY (`enrollment_by`) REFERENCES `users` (`userid`),
  CONSTRAINT `patient_enrolment_communities_id_fk` FOREIGN KEY (`community_id`) REFERENCES `communities` (`community_id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=41774 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

