--
-- Table structure for table `patient_enrolment_trx`
--

DROP TABLE IF EXISTS `patient_enrolment_trx`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `patient_enrolment_trx` (
  `enrolment_row_id` int(11) NOT NULL,
  `enrolment_trx_id` int(11) NOT NULL AUTO_INCREMENT,
  `enrolment_uid` varchar(20) NOT NULL,
  `current_date_of_enrolment` date NOT NULL,
  `exp_date_of_current_enrolment` date NOT NULL,
  `enrolment_status_id` int(11) DEFAULT NULL,
  `enrolled_by` int(11) NOT NULL,
  `payment_plan_id` int(11) DEFAULT NULL,
  `service_duration_id` int(11) NOT NULL,
  `deleted_yn` char(1) DEFAULT 'N',
  `last_updated_by` int(11) DEFAULT NULL,
  `last_updated_date` datetime DEFAULT NULL,
  `enrolment_current_status` varchar(20) DEFAULT NULL,
  `medical_condition_id` int(11) NOT NULL DEFAULT '1',
  `discount_value` int(11) DEFAULT NULL,
  `plandiscounted` tinyint(4) DEFAULT '1',
  PRIMARY KEY (`enrolment_trx_id`,`current_date_of_enrolment`,`exp_date_of_current_enrolment`,`enrolled_by`,`enrolment_uid`),
  UNIQUE KEY `enrolment_uid` (`enrolment_uid`,`current_date_of_enrolment`),
  UNIQUE KEY `enrolment_uid_k` (`enrolment_uid`,`exp_date_of_current_enrolment`),
  KEY `patient_enrol_trx_enrol_stat_id_fk_idx` (`enrolment_status_id`),
  KEY `patient_enrol_trx_users_userid_fk_idx` (`enrolled_by`),
  KEY `patient_enrol_trx_pay_plan_id_fk_idx` (`payment_plan_id`),
  KEY `patient_enrolment_trx_row_id_fk` (`enrolment_row_id`),
  KEY `service_duration_id` (`service_duration_id`),
  KEY `enrolment_trx_id` (`enrolment_trx_id`),
  CONSTRAINT `patient_enrol_trx_enrol_stat_id_fk` FOREIGN KEY (`enrolment_status_id`) REFERENCES `enrolment_status` (`enrolment_status_id`),
  CONSTRAINT `patient_enrol_trx_pay_plan_id_fk` FOREIGN KEY (`payment_plan_id`) REFERENCES `payment_plan` (`payment_plan_id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `patient_enrol_trx_users_userid_fk` FOREIGN KEY (`enrolled_by`) REFERENCES `users` (`userid`),
  CONSTRAINT `patient_enrolment_trx_payment_plan_dtl_plan_id_fk` FOREIGN KEY (`payment_plan_id`) REFERENCES `payment_plan_dtl` (`payment_plan_id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=39770 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

